'use strict';
const Meta=window.Meta={
  inBattle:false,screen:'home',chapter:0,filter:'owned',slot:0,selectedQuest:0,selectedHero:'evelyn',resultReward:null,summonTimer:null,
  init(){let storage;try{storage=localStorage;}catch{}this.model=new AbyssProgress.Campaign(storage);paused=true;this.render();document.addEventListener('click',e=>{const b=e.target.closest('[data-meta]');if(!b||b.disabled)return;this.action(b.dataset.meta,b.dataset);});setInterval(()=>{if(!this.inBattle){this.model.tick();this.updateResources();}},15000);},
  icon(name){const paths={home:'M3 11 12 3l9 8M5 10v11h14V10M9 21v-7h6v7',quest:'m4 6 5-3 6 3 5-3v15l-5 3-6-3-5 3V6Zm5-3v15m6-12v15',summon:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',heroes:'M8 3h8l4 7-8 12L4 10l4-7Zm-4 7h16M8 3l4 7 4-7m-4 7v12',shop:'M4 8h16l-1 13H5L4 8Zm4 0V6a4 4 0 0 1 8 0v2',gift:'M3 8h18v5H3zM5 13v8h14v-8M12 8v13M12 8C3 8 6 0 10 4l2 4Zm0 0c9 0 6-8 2-4l-2 4Z',mission:'M6 3h12v18H6zM9 7h6M9 11h6M9 15l2 2 4-4',gear:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',team:'M8 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6Zm9 1a2 2 0 1 0 0 4 2 2 0 0 0 0-4ZM2 21v-4a6 6 0 0 1 12 0v4m1-8a5 5 0 0 1 7 4v4',arrow:'M4 12h16m-6-6 6 6-6 6'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.summon}"/></svg>`;},
  num(n){return n.toLocaleString();},
  stars(n){return '★'.repeat(n);},
  image(h){return `assets/${h.art}-v2.jpg`;},
  render(){const s=this.model.state,nav=[['home','大厅'],['quest','冒险'],['heroes','调查员'],['summon','召唤'],['shop','商店']];
    $('campaignApp').innerHTML=`<header class="account-bar"><button class="account" data-meta="settings" aria-label="设置与存档"><img src="${this.image(this.model.hero(s.team[0]))}" alt=""><span><b>密斯卡托尼克</b><small>RANK ${1+Math.floor(s.rankExp/300)} <i class="rank-track"><i style="width:${s.rankExp%300/3}%"></i></i></small></span></button><div class="currencies"><button data-meta="energy" aria-label="查看体力"><span class="energy-glyph">ϟ</span><b id="resourceStamina">${s.stamina}/60</b></button><button data-meta="nav" data-screen="shop" aria-label="金币商店"><span class="coin-glyph">◉</span><b id="resourceGold">${this.num(s.gold)}</b></button><button data-meta="nav" data-screen="summon" aria-label="使用星晶召唤"><span class="gem-glyph">◆</span><b id="resourceGems">${this.num(s.gems)}</b><i>+</i></button></div></header><aside class="campaign-brand"><div class="brand-emblem"><img src="assets/sigil.svg" alt=""></div><span>ABYSSAL<br>RICOCHET</span><h1>深渊弹珠</h1><p>群星之下 · 旧日回响</p><div class="brand-rule"></div><div class="brand-story">那些无法被记录的故事，<br>由你来终结。</div><button data-meta="missions">${this.icon('mission')} 调查任务</button><button data-meta="settings">${this.icon('gear')} 设置 / 存档</button><small>单人冒险 · 本地存档</small></aside><main class="campaign-content" id="campaignContent" tabindex="-1">${this.content()}</main><nav class="main-nav" aria-label="游戏主菜单">${nav.map(([id,name])=>`<button data-meta="nav" data-screen="${id}" class="${this.screen===id?'selected':''}" ${this.screen===id?'aria-current="page"':''}>${this.icon(id)}<span>${name}</span>${id==='summon'&&s.gems>=2700?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav>`;
    if(this.model.saveError)toast('浏览器禁止保存，当前进度仅在本次打开期间保留');
  },
  updateResources(){const s=this.model.state;if($('resourceStamina'))$('resourceStamina').textContent=`${s.stamina}/60`;if($('resourceGold'))$('resourceGold').textContent=this.num(s.gold);if($('resourceGems'))$('resourceGems').textContent=this.num(s.gems);},
  heading(en,title,extra=''){return `<div class="screen-heading"><div><span>${en}</span><h2>${title}</h2></div>${extra}</div>`;},
  content(){return ({home:()=>this.home(),quest:()=>this.quests(),heroes:()=>this.heroes(),summon:()=>this.summon(),shop:()=>this.shop()})[this.screen]();},
  home(){const s=this.model.state,h=this.model.hero(s.team[0]),next=AbyssProgress.QUESTS.find(q=>!s.clears[q.id])||AbyssProgress.QUESTS[8],ready=AbyssProgress.MISSIONS.filter(m=>this.model.missionReady(m)&&!s.claimed.includes(m.id)).length;
    return `<section class="home-scene"><div class="home-location"><span>THE MISKATONIC SOCIETY</span><strong>秘星观测所</strong><small>1926 · NOVEMBER · 17</small></div><div class="scene-dust" aria-hidden="true"></div><div class="home-orbit" aria-hidden="true"></div><button class="lobby-character" data-meta="hero" data-key="${h.key}" aria-label="查看${h.name}"><img src="${this.image(h)}" alt="${h.role} ${h.name}"></button><div class="home-shortcuts"><button data-meta="daily" class="${this.model.dailyReady()?'notified':''}">${this.icon('gift')}<span>每日补给</span></button><button data-meta="missions" class="${ready?'notified':''}">${this.icon('mission')}<span>调查任务</span></button><button data-meta="settings">${this.icon('gear')}<span>设置</span></button></div><div class="lobby-hero-name"><span>${h.element} · ${h.role}</span><h2>${h.name}</h2><div class="gold-stars">${this.stars(h.rarity)}</div><p>「${h.lore}」</p></div><div class="home-lower"><button class="event-banner" data-meta="nav" data-screen="summon"><img src="assets/nyra-v2.jpg" alt=""><span><small>常驻契约 · 六星调查员</small><b>潮汐的预言</b><em>奈莉娅 / 奥利安</em></span><i>召唤 ›</i></button><div class="home-team"><span>出战小队</span><div>${s.team.map(k=>`<button data-meta="hero" data-key="${k}" aria-label="查看${this.model.hero(k).name}"><img src="${this.image(this.model.hero(k))}" alt=""><small>${s.owned[k].level}</small></button>`).join('')}</div><button class="edit-team" data-meta="team">${this.icon('team')}编队</button></div><button class="embossed-button sortie-button" data-meta="nav" data-screen="quest"><span>${this.icon('quest')}</span><div><b>开始调查</b><small>主线 ${next.number} · ${next.name}</small></div><span>›</span></button></div></section>`;
  },
  quests(){const s=this.model.state,c=AbyssProgress.CHAPTERS[this.chapter];return `<section class="standard-screen quest-screen">${this.heading('EXPEDITIONS','深渊调查',`<span class="small-counter">${Object.keys(s.clears).length} / 9 完成</span>`)}<div class="chapter-tabs">${AbyssProgress.CHAPTERS.map((c,i)=>`<button data-meta="chapter" data-index="${i}" class="${i===this.chapter?'active':''}"><small>CHAPTER 0${i+1}</small><b>${c.name}</b></button>`).join('')}</div><div class="chapter-art chapter-${this.chapter}"><div><span>${c.en}</span><h3>${c.name}</h3><p>${c.story}</p></div><img src="assets/${['watcher-v3','warden-v3','boss-v2'][this.chapter]}.png" alt="本章异变生物"></div><div class="quest-list">${AbyssProgress.QUESTS.filter(q=>q.chapter===this.chapter).map(q=>{const unlocked=this.model.unlocked(q.id),clear=s.clears[q.id];return `<button data-meta="quest" data-id="${q.id}" class="quest-entry ${unlocked?'':'locked'}" ${!unlocked?'disabled':''}><span class="quest-number">${q.number}</span><span class="quest-info"><small>${q.boss?'首领讨伐':'主线调查'} · 3 WAVE</small><b>${q.name}</b><em>${clear?`<span class="gold-stars">${this.stars(clear.stars)}${'☆'.repeat(3-clear.stars)}</span> 调查完成`:unlocked?`首次通关 ◆ ${q.gems}`:'完成前一关后解锁'}</em></span><span class="quest-cost">${unlocked?`ϟ ${q.cost}<small>推荐 Lv.${q.level}</small>`:'未解锁'}<i>›</i></span></button>`;}).join('')}</div><div class="screen-note">首次通关获得星晶 · 重复调查可收集强化材料</div></section>`;},
  heroCard(h,opts={}){const o=this.model.state.owned[h.key];return `<button class="recruit-card rarity-${h.rarity} ${o?'':'unowned'} ${opts.selected?'card-selected':''}" data-meta="${opts.action||'hero'}" data-key="${h.key}" style="--hero-tint:${h.color}" aria-label="${h.name}${o?`，等级 ${o.level}`:'，未获得'}"><img src="${this.image(h)}" alt="" loading="lazy"><span class="recruit-element">${h.element}</span>${opts.badge?`<span class="recruit-badge">${opts.badge}</span>`:''}<div class="recruit-caption"><span>${this.stars(h.rarity)}</span><strong>${h.name}</strong><small>${o?`Lv.${o.level} <em>${h.type}</em>`:'未获得'}</small></div></button>`;},
  heroes(){const s=this.model.state,owned=Object.keys(s.owned).length,items=AbyssProgress.CATALOG.filter(h=>this.filter==='all'||!!s.owned[h.key]).sort((a,b)=>b.rarity-a.rarity);return `<section class="standard-screen">${this.heading('INVESTIGATORS','调查员档案',`<span class="small-counter">${owned} / ${AbyssProgress.CATALOG.length}</span>`)}<button class="formation-strip" data-meta="team"><span>${this.icon('team')}<b>小队编成</b><small>总攻击 ${this.model.power()}</small></span><div>${s.team.map(k=>`<img src="${this.image(this.model.hero(k))}" alt="${this.model.hero(k).name}">`).join('')}</div><i>›</i></button><div class="section-toolbar"><div class="segmented"><button data-meta="filter" data-filter="owned" class="${this.filter==='owned'?'active':''}">已契约 ${owned}</button><button data-meta="filter" data-filter="all" class="${this.filter==='all'?'active':''}">全部图鉴</button></div><small>稀有度 ↓</small></div><div class="roster-grid">${items.map(h=>this.heroCard(h,{badge:s.team.includes(h.key)?'出战':''})).join('')}</div><div class="material-wallet"><span>◈ 残响 <b>${this.num(s.exp)}</b></span><span>✧ 古印 <b>${s.sigils}</b></span><span>◉ 金币 <b>${this.num(s.gold)}</b></span></div><p class="screen-note">点击角色查看技能、强化与觉醒</p></section>`;},
  summon(){const s=this.model.state;return `<section class="summon-screen">${this.heading('ASTRAL COVENANT','群星契约',`<button class="text-button" data-meta="rates">召唤详情</button>`)}<div class="summon-art"><div class="summon-halo"></div><img class="summon-knight" src="assets/orion-v2.jpg" alt="星骸骑士 奥利安"><img class="summon-oracle" src="assets/nyra-v2.jpg" alt="潮汐神谕 奈莉娅"><div class="summon-titles"><span>星海的彼岸，谁在回应你的呼唤</span><h2>潮汐的预言</h2><div class="gold-stars">★★★★★★</div><p>奈莉娅 <i>＆</i> 奥利安</p></div></div><div class="summon-controls"><div class="summon-pity"><span>十连必得 <b>五星及以上</b></span><span>六星保底 <b>${s.pity} / 30</b></span></div><div class="summon-buttons"><button class="silver-button" data-meta="pull" data-count="1" ${s.gems<300?'disabled':''}><b>召唤一次</b><small>◆ 300</small></button><button class="embossed-button" data-meta="pull" data-count="10" ${s.gems<2700?'disabled':''}><i class="discount-ribbon">九折契约</i><b>召唤十次</b><small>◆ 2,700</small></button></div><p class="screen-note">常驻召唤 · 星晶由游戏内获得 · 重复角色转为魂片与幸运值</p>${s.lastResults.length?'<button class="text-button" data-meta="last-pull">查看上次召唤</button>':''}</div></section>`;},
  shop(){const s=this.model.state;return `<section class="standard-screen shop-screen">${this.heading('THE NIGHT MARKET','夜行商会')}<div class="shop-intro"><span>「能带走的，才是属于你的。」</span><p>用调查所得，换取下一次出发的力量。</p></div><div class="shop-items">${[['energy','ϟ','浓缩灵药','恢复 30 体力（上限 60）','◆ 50'],['exp','◈','残响结晶 ×30','用于提升调查员等级','◉ 1,000'],['sigil','✧','古印碎石 ×3','达到等级上限后用于觉醒','◆ 100']].map(([id,icon,name,desc,cost])=>`<div class="shop-item"><div class="item-crystal ${id}">${icon}</div><div><h3>${name}</h3><p>${desc}</p><button data-meta="buy-confirm" data-item="${id}" class="silver-button">${cost} · 兑换</button></div></div>`).join('')}</div><div class="material-wallet"><span>◈ 残响 <b>${s.exp}</b></span><span>✧ 古印 <b>${s.sigils}</b></span></div><p class="screen-note">商会只消耗游戏资源，无充值与现金交易。</p></section>`;},
  showHero(key){this.selectedHero=key;const h=this.model.hero(key);if(!h)return;const o=this.model.state.owned[key],max=o?20+o.awake*20:20,s=this.model.state,five=Array.from({length:o?Math.min(5,max-o.level):0},(_,i)=>o.level+i),fiveGold=five.reduce((n,l)=>n+l*65,0),fiveExp=five.reduce((n,l)=>n+Math.ceil(l*.8+2),0);openModal('hero',`<div class="hero-detail"><div class="detail-art" style="--hero-tint:${h.color}"><img src="${this.image(h)}" alt="${h.name}"><div><small>${h.element} · ${h.role} · ${h.type}</small><h2>${h.name}</h2><span class="gold-stars">${this.stars(h.rarity)}</span></div></div><div class="detail-body"><p class="hero-lore">${h.lore}</p><div class="hero-stats"><div><small>等级</small><b>${o?o.level:1}<em> / ${max}</em></b></div><div><small>攻击</small><b>${h.attack}</b></div><div><small>生命</small><b>${h.hp}</b></div><div><small>幸运</small><b>${o?.luck||1}</b></div></div><div class="skill-description"><span>友情援护</span><h3>${h.skill}</h3><p>${['追击生命最低的敌人，造成 '+Math.round(180*h.supportScale)+' 伤害。','攻击全体敌人，每个目标造成 '+Math.round(100*h.supportScale)+' 伤害。','恢复 '+Math.round(500*h.supportScale)+' 生命与 5 理智，攻击最近敌人。','攻击生命最高的敌人，造成 '+Math.round(240*h.supportScale)+' 伤害。'][h.supportKind]}</p><small>${h.type==='贯通'?'贯通型：穿过敌人持续攻击，仍会被墙壁与障碍反弹。':'反射型：利用敌人、墙壁之间的反弹制造连续伤害。'}</small></div>${o?`<div class="growth-title"><b>灵魂强化</b><small>◈ ${s.exp} 残响 · ◉ ${this.num(s.gold)}</small></div><div class="growth-buttons"><button class="silver-button" data-meta="train" data-count="1" ${o.level>=max?'disabled':''}>升级 1 次<small>◈ ${Math.ceil(o.level*.8+2)} / ◉ ${o.level*65}</small></button><button class="embossed-button" data-meta="train" data-count="5" ${o.level>=max?'disabled':''}>强化 ${five.length||5} 级<small>◈ ${fiveExp} / ◉ ${fiveGold}</small></button></div><button class="awaken-button" data-meta="awaken" ${o.awake>=4?'disabled':''}><span>✧ 觉醒 ${o.awake} / 4</span><small>${o.awake>=4?'已完全觉醒':`Lv.${max} 后解锁上限 ${max+20} · ✧ ${3*(o.awake+1)} / ◉ ${2000*(o.awake+1)}`}</small></button><div class="shards-row"><span>魂片 ${o.shards} · 队长幸运增加金币掉落</span><button class="text-button" data-meta="shards" ${o.shards<20?'disabled':''}>20 魂片换 30 残响</button></div><button class="text-button detail-team-button" data-meta="team">${this.icon('team')} 编入小队</button>`:`<div class="unowned-note">尚未签订契约 · 可在群星召唤中获得</div><button class="embossed-button" data-meta="go-summon">前往召唤</button>`}</div></div>`);},
  showTeam(){const s=this.model.state;openModal('team',`<div class="modal-kicker">EXPEDITION FORMATION</div><h2>小队编成</h2><p>选择位置，再选择调查员；已在队伍中的角色会交换位置。</p><div class="team-slots">${s.team.map((k,i)=>`<button data-meta="slot" data-slot="${i}" class="${i===this.slot?'active':''}"><small>${i===0?'队长':`位置 ${i+1}`}</small><img src="${this.image(this.model.hero(k))}" alt="${this.model.hero(k).name}"><strong>${this.model.hero(k).name}</strong><span>Lv.${s.owned[k].level}</span></button>`).join('')}</div><div class="team-power"><span>总攻击 <b>${this.model.power()}</b></span><span>总生命 <b>${this.num(this.model.party().reduce((n,h)=>n+h.hp,0))}</b></span></div><div class="team-options">${AbyssProgress.CATALOG.filter(h=>s.owned[h.key]).map(h=>this.heroCard(h,{action:'equip',badge:s.team.includes(h.key)?`${s.team.indexOf(h.key)+1}P`:'',selected:s.team[this.slot]===h.key})).join('')}</div><div class="modal-actions"><button class="primary-button" data-meta="team-done">编成完成</button></div>`);},
  showQuest(id){this.selectedQuest=id;const q=AbyssProgress.QUESTS[id],s=this.model.state;openModal('quest',`<div class="modal-kicker">EXPEDITION ${q.number} · 3 WAVES</div><h2>${q.name}</h2><p>${AbyssProgress.CHAPTERS[q.chapter].story}</p><div class="quest-brief"><img src="assets/${['watcher-v3','warden-v3','boss-v2'][q.chapter]}.png" alt="敌人预览"><div><span>推荐等级 <b>Lv.${q.level}</b></span><span>体力消耗 <b>ϟ ${q.cost}</b></span><span>当前小队攻击 <b>${this.model.power()}</b></span></div></div><h3 class="minor-title">调查奖励</h3><div class="reward-chips"><span>◉ ${q.gold}</span><span>◈ ${q.exp}</span><span>✧ ${q.sigils}</span>${!s.clears[id]?`<span class="gem-reward">首通 ◆ ${q.gems}</span>`:''}</div><button class="formation-strip compact" data-meta="team"><b>出战小队</b><div>${s.team.map(k=>`<img src="${this.image(this.model.hero(k))}" alt="${this.model.hero(k).name}">`).join('')}</div><i>›</i></button><p class="modal-note">3 星条件：完成调查、剩余生命 ≥ 50%、弹射次数 ≤ 16。退出或刷新会消耗本次体力。</p><div class="modal-actions"><button class="secondary-button" data-action="resume">取消</button><button class="primary-button" data-meta="start">出发 · ϟ ${q.cost}</button></div>`);},
  start(){const options=this.model.begin(this.selectedQuest);this.inBattle=true;this.resultReward=null;clearTimeout(resultTimer);clearTimeout(messageTimer);$('modal').close();modalType='';$('campaignApp').hidden=true;$('battleShell').hidden=false;document.body.className='in-battle';particles=[];floaters=[];beams=[];rings=[];trail=[];aim=null;shake=0;log.length=0;game.reset(options);BattleFX.reset();paused=false;lastTime=performance.now();accumulator=0;$('aimHelp').style.display='';updateUI();resizeCanvas();canvas.focus({preventScroll:true});window.scrollTo(0,0);},
  pause(){if(['cleared','victory','defeat'].includes(game.mode)){this.battleResult();return;}openModal('pause',`<div class="modal-kicker">EXPEDITION PAUSED</div><h2>调查暂停</h2><p>${game.stages[game.stage].name} · 第 ${game.turn} 回合</p><div class="result-stats"><div><strong>${game.hp}</strong><span>生命</span></div><div><strong>${game.sanity}</strong><span>理智</span></div><div><strong>${game.score}</strong><span>得分</span></div></div><div class="modal-actions"><button class="secondary-button" data-meta="leave-battle">退出调查</button><button class="primary-button" data-action="resume">继续战斗</button></div>`);},
  battleResult(){const won=game.mode==='victory';if(game.mode==='cleared'){openModal('result',`<div class="modal-kicker">WAVE ${game.stage+1} CLEAR</div><div class="result-symbol">✧</div><h2 class="result-title">封印正在松动</h2><p class="center-text">本波敌人已被驱散。<br>下一波恢复 1,000 生命与 15 理智。</p><div class="modal-actions"><button class="primary-button" data-action="next-stage">${game.stage===1?'首领战 · 进入最后一波':'继续深入 · 下一波'} ↗</button></div>`);return;}
    if(!won&&game.mode!=='defeat')return;if(!this.resultReward)this.resultReward=this.model.finish(won,{hpRatio:game.hp/game.maxHp,shots:game.totalShots,score:game.score});const r=this.resultReward||{won:false};
    openModal('result',`<div class="modal-kicker">${won?'EXPEDITION COMPLETE':'EXPEDITION LOST'}</div><div class="result-symbol">${won?'✧':'☾'}</div><h2 class="result-title">${won?'调查完成':'灯火尚未熄灭'}</h2>${won?`<div class="result-stars">${this.stars(r.stars)}${'☆'.repeat(3-r.stars)}</div><p class="center-text">${r.first?'首次调查完成 · 新关卡已解锁':'调查报告已归档'}<br>奖励已存入背包</p><div class="reward-chips result-rewards"><span>◉ ${r.gold}</span><span>◈ ${r.exp}</span><span>✧ ${r.sigils}</span>${r.gems?`<span>◆ ${r.gems}</span>`:''}</div>`:'<p class="center-text">强化调查员、调整小队与弹射角度，再次挑战。<br>本次未获得通关奖励。</p>'}<div class="result-stats"><div><strong>${this.num(game.score)}</strong><span>调查评分</span></div><div><strong>${game.maxCombo}</strong><span>最高连击</span></div><div><strong>${game.totalShots}</strong><span>弹射次数</span></div></div><div class="modal-actions"><button class="secondary-button" data-meta="return-home">返回大厅</button><button class="primary-button" data-meta="return-quests">继续冒险</button></div>`);
  },
  returnTo(screen){clearTimeout(resultTimer);clearTimeout(messageTimer);this.model.abandon();this.inBattle=false;paused=true;aim=null;accumulator=0;$('modal').close();modalType='';$('battleShell').hidden=true;$('campaignApp').hidden=false;document.body.className='in-lobby';this.screen=screen;this.chapter=AbyssProgress.QUESTS[this.selectedQuest].chapter;this.render();window.scrollTo(0,0);},
  reveal(results){clearTimeout(this.summonTimer);const six=results.some(h=>h.rarity===6);openModal('summon-results',`<div class="modal-kicker">COVENANT SEALED</div><h2>${six?'群星回应了你':'契约成立'}</h2><p>新伙伴已加入，重复角色已转为魂片并提升幸运。</p><div class="summon-results ${results.length===1?'single-pull':''}">${results.map((r,i)=>this.heroCard(this.model.hero(r.key),{badge:r.isNew?'NEW':`魂片 +${r.shards}`} )).join('')}</div><div class="modal-actions"><button class="primary-button" data-meta="pull-done">收下契约</button></div>`);this.updateResources();tone(six?620:420,.4,'triangle',.04);},
  missions(){const s=this.model.state;openModal('missions',`<div class="modal-kicker">SOCIETY COMMISSIONS</div><h2>调查任务</h2><div class="mission-list">${AbyssProgress.MISSIONS.map(m=>{const claimed=s.claimed.includes(m.id),ready=this.model.missionReady(m);return `<div class="mission"><div><h3>${m.name}</h3><p>${m.desc} ${m.stat?`(${Math.min(s.stats[m.stat],m.target)}/${m.target})`:''}</p><small>◆ ${m.gems} · ◉ ${m.gold}</small></div><button data-meta="claim" data-id="${m.id}" class="${ready&&!claimed?'primary-button':'secondary-button'}" ${!ready||claimed?'disabled':''}>${claimed?'已领取':ready?'领取':'进行中'}</button></div>`;}).join('')}</div>`);},
  settings(){openModal('settings',`<div class="modal-kicker">SOCIETY RECORDS</div><h2>设置与调查记录</h2><div class="settings-row"><span>战斗音效</span><button class="silver-button" data-meta="sound">${sound?'已开启':'已关闭'}</button></div><div class="settings-row"><span>玩法说明</span><button class="silver-button" data-meta="guide">打开手册</button></div><h3 class="minor-title">本地存档</h3><p>调查员、星晶和关卡进度会自动保存在当前浏览器。更换设备前可导出存档，再在新设备导入。</p><div class="growth-buttons"><button class="silver-button" data-meta="export">导出存档</button><label class="silver-button import-label">导入存档<input type="file" id="saveImport" accept="application/json,.json"></label></div><p class="modal-note">原创克苏鲁单人弹射 RPG · 12 位调查员 / 9 关调查<br>当前版本包含完整单机养成循环，无联网联机或账号同步。</p>`);$('saveImport').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>200000)throw new Error('存档文件过大');const raw=JSON.parse(await file.text());if(raw.version!==3||!raw.owned||typeof raw.owned!=='object')throw new Error('不是有效的深渊弹珠存档');this.pendingImport=raw;openModal('import-confirm','<div class="modal-kicker">IMPORT SAVE</div><h2>载入这份调查记录？</h2><p>将覆盖当前浏览器中的游戏进度，建议先导出备份。</p><div class="modal-actions"><button class="secondary-button" data-meta="settings">取消</button><button class="primary-button" data-meta="import-confirm">确认载入</button></div>');}catch(err){toast(err.message);}});},
  action(action,d){try{switch(action){
    case'nav':this.screen=d.screen;this.render();break;
    case'chapter':this.chapter=Number(d.index);this.render();break;
    case'filter':this.filter=d.filter;this.render();break;
    case'hero':this.showHero(d.key);break;
    case'quest':this.showQuest(Number(d.id));break;
    case'start':this.start();break;
    case'team':this.returnQuest=modalType==='quest';this.showTeam();break;
    case'slot':this.slot=Number(d.slot);this.showTeam();break;
    case'equip':this.model.equip(d.key,this.slot);this.showTeam();this.render();tone(400,.08);break;
    case'team-done':if(this.returnQuest){this.returnQuest=false;this.showQuest(this.selectedQuest);}else{closeModal();this.render();}break;
    case'train':{const n=this.model.train(this.selectedHero,Number(d.count));this.showHero(this.selectedHero);this.render();tone(560,.2);toast(`强化成功 · 等级提升 ${n} 级`);break;}
    case'awaken':this.model.awaken(this.selectedHero);this.showHero(this.selectedHero);this.render();tone(650,.45);toast('觉醒完成 · 等级上限与基础属性提升');break;
    case'shards':this.model.exchangeShards(this.selectedHero);this.showHero(this.selectedHero);this.render();toast('已兑换 30 残响');break;
    case'go-summon':closeModal();this.screen='summon';this.render();break;
    case'pull':{const results=this.model.summon(Number(d.count));this.pendingResults=results;this.render();openModal('summoning',`<div class="ritual-scene"><div class="ritual-ring"></div><div class="ritual-core">✧</div><h2>群星正在回应</h2><p>以古老的誓约，唤醒沉睡的灵魂</p><button class="text-button" data-meta="reveal">跳过动画 ›</button></div>`);tone(110,.8,'sine',.05);this.summonTimer=setTimeout(()=>{if(modalType==='summoning')this.reveal(results);},reduced?100:1700);break;}
    case'reveal':this.reveal(this.pendingResults);break;
    case'last-pull':this.reveal(this.model.state.lastResults);break;
    case'pull-done':closeModal();this.render();break;
    case'rates':openModal('rates',`<div class="modal-kicker">COVENANT DETAILS</div><h2>群星契约 · 召唤规则</h2><div class="rate-row"><b>★★★★★★</b><span>4%</span></div><div class="rate-row"><b>★★★★★</b><span>24%</span></div><div class="rate-row"><b>★★★★</b><span>72%</span></div><p>同一稀有度内各角色等概率。连续 29 次未获得六星，第 30 次必得六星；获得六星后计数归零，单抽与十连共用计数。</p><p>十连前 9 次均未获得五星及以上时，第 10 次至少为五星；六星保底优先。十连消耗 2,700 星晶，单次消耗 300 星晶。</p><p>重复四 / 五 / 六星分别转为 20 / 40 / 80 魂片，并增加 5 幸运（上限 99）。20 魂片可兑换 30 强化残响。队长每增加 1 点幸运（初始 1），通关金币增加 1%。</p><p class="modal-note">本池为常驻池，无限时概率提升。所有星晶由游戏内获得。</p>`);break;
    case'daily':this.model.dailyClaim();this.render();openModal('daily',`<div class="modal-kicker">DAILY SUPPLY</div><div class="result-symbol">✧</div><h2 class="center-text">灯塔送来了补给</h2><div class="reward-chips"><span>◆ 300 星晶</span><span>◈ 30 残响</span><span>ϟ 30 体力</span></div><p class="center-text">已收下今日补给 · 体力最多恢复至 60</p><div class="modal-actions"><button class="primary-button" data-action="resume">收下补给</button></div>`);break;
    case'missions':this.missions();break;
    case'claim':this.model.claim(d.id);this.missions();this.render();toast('任务奖励已领取');break;
    case'buy-confirm':this.pendingItem=d.item;openModal('buy',`<div class="modal-kicker">NIGHT MARKET</div><h2>确认兑换？</h2><p>${{energy:'消耗 50 星晶，恢复 30 体力（最多 60）。',exp:'消耗 1,000 金币，获得 30 强化残响。',sigil:'消耗 100 星晶，获得 3 古印。'}[d.item]}</p><div class="modal-actions"><button class="secondary-button" data-action="resume">取消</button><button class="primary-button" data-meta="buy">确认兑换</button></div>`);break;
    case'buy':this.model.buy(this.pendingItem);closeModal();this.render();toast('兑换完成 · 物资已入库');break;
    case'energy':openModal('energy',`<div class="modal-kicker">EXPEDITION ENERGY</div><h2>体力 ${this.model.state.stamina} / 60</h2><p>每 5 分钟恢复 1 点体力，上限 60。每日补给与夜行商会也提供恢复道具。</p><div class="modal-actions"><button class="secondary-button" data-meta="daily">领取每日补给</button><button class="primary-button" data-meta="energy-shop">前往商会</button></div>`);break;
    case'energy-shop':closeModal();this.screen='shop';this.render();break;
    case'settings':this.settings();break;
    case'sound':$('soundButton').click();this.settings();break;
    case'guide':showGuide();break;
    case'export':{this.model.save();const blob=new Blob([JSON.stringify(this.model.state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='abyssal-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已导出');break;}
    case'import-confirm':this.model.state=AbyssProgress.normalize(this.pendingImport);this.model.save();this.pendingImport=null;closeModal();this.render();toast('调查记录已载入');break;
    case'leave-battle':if(['victory','defeat','cleared'].includes(game.mode)){this.battleResult();break;}openModal('leave',`<div class="modal-kicker">LEAVE EXPEDITION</div><h2>结束本次调查？</h2><p>本次体力不会返还，未通关无法领取奖励。已有角色与养成进度会保留。</p><div class="modal-actions"><button class="secondary-button" data-action="resume">继续战斗</button><button class="primary-button" data-meta="return-quests">结束调查</button></div>`);break;
    case'return-home':this.returnTo('home');break;
    case'return-quests':this.returnTo('quest');break;
  }}catch(err){toast(err.message);}if(this.model.saveError)toast('进度未能保存，请在设置中导出备份');}
};
Meta.init();
